import {useEffect, useState} from 'react';
import axios from "axios";
import { BASE_URL } from '../api';

const socket= io(BASE_URL);

function Chat() {
    const [chats,setChats]= useState('');
    const [receiveChats,setReceiveChats] = useState([])

    chatPayload={
      'sendUser':'',
      'recieverUser':'',
      'Message':''
    }

    useEffect(() => {
      let username=localStorage.getItem('username');
      socket.emit("join",{user_name:username});

      socket.on("receive_message", (data)=>{
        setReceiveChats((prev) => [...prev, data]);
      })
    });
    const setChat = (e) =>{
        setChats(e.target.value);
    };



    const sendChat = async () => {
      try{
        chatPayload.sendUser=username;
        chatPayload.recieverUser=localStorage.getItem('ToUser');
        chatPayload.Message=chats;
        // accessToken=localStorage.getItem(accessToken)
        // const response = await axios.post(CHAT_API,chatPayload,
        //   {headers: {Authorization: `Bearer ${accessToken}`}}
        // );
        socket.emit("send_message",chatPayload);

      } catch (error) {
        console.error('Error sending chat:', error);
      };
    }





    return (
            <div className="terminal">
              <div className="terminal-header">
                <span className="led led-red" />
                <span className="led led-yellow" />
                <span className="led led-green" />
                <span className="title">/chat/terminal</span>
              </div>
              <div className="terminal-body" >
                  <div className="line">
                    {receiveChats.map}
                  </div>
              </div>
              <div className="terminal-input">
                <span className="prompt">{" > "}</span>
                <textarea
                  rows={1}
                  placeholder="type here and press Enter… (Shift+Enter for newline)"
                  onChange={setChat}
                  onKeyDown={(e) => {
                    if (e.key === 'Enter' && !e.shiftKey) {
                      e.preventDefault();
                      sendChat();
                    }
                  }}
                  value={chats}
                />
              </div>
            </div>
    );
}
export default Chat;
